  <script>
    const hamburger = document.getElementById('hamburger');
    const drawer = document.getElementById('mobile-drawer');
    hamburger?.addEventListener('click', () => {
      const expanded = hamburger.getAttribute('aria-expanded') === 'true';
      hamburger.setAttribute('aria-expanded', String(!expanded));
      drawer.classList.toggle('open');
    });

    drawer?.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        drawer.classList.remove('open');
        hamburger.setAttribute('aria-expanded', 'false');
      });
    });

    const modal = document.getElementById('donate-modal');
    const openDonateButtons = document.querySelectorAll('[data-open-donate]');
    const closeModal = document.getElementById('close-modal');

    function openModal() {
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }

    function closeDonateModal() {
      modal.classList.remove('open');
      modal.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
    }

    openDonateButtons.forEach(btn => btn.addEventListener('click', (e) => {
      e.preventDefault();
      openModal();
    }));

    closeModal?.addEventListener('click', closeDonateModal);
    modal?.addEventListener('click', (e) => {
      if (e.target === modal) closeDonateModal();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('open')) closeDonateModal();
    });

    const amountGrid = document.getElementById('amount-grid');
    let selectedAmount = null;
    amountGrid?.querySelectorAll('.amount-option').forEach(option => {
      option.addEventListener('click', () => {
        amountGrid.querySelectorAll('.amount-option').forEach(x => x.classList.remove('selected'));
        option.classList.add('selected');
        selectedAmount = option.dataset.amount;
      });
    });

    document.getElementById('donate-submit')?.addEventListener('click', () => {
      const customValue = document.getElementById('custom-amount').value;
      const amount = selectedAmount === 'custom' ? customValue : selectedAmount;
      alert(amount ? `Thank you! You selected a $${amount} donation.` : 'Please select or enter a donation amount.');
    });

    document.querySelectorAll('.accordion-item').forEach(item => {
      const trigger = item.querySelector('.accordion-trigger');
      const content = item.querySelector('.accordion-content');
      const icon = trigger.querySelector('span');
      trigger.addEventListener('click', () => {
        const open = item.classList.contains('open');
        item.classList.toggle('open');
        trigger.setAttribute('aria-expanded', String(!open));
        icon.textContent = open ? '+' : '−';
        content.style.maxHeight = open ? '0px' : content.scrollHeight + 'px';
      });
    });

    const newsTrack = document.getElementById('news-track');
    const newsCards = newsTrack ? Array.from(newsTrack.children) : [];
    let newsIndex = 0;

    function renderNews() {
      if (!newsTrack || !newsCards.length) return;
      newsTrack.style.transform = `translateX(-${newsIndex * 100}%)`;
    }

    document.getElementById('news-next')?.addEventListener('click', () => {
      newsIndex = (newsIndex + 1) % newsCards.length;
      renderNews();
    });

    document.getElementById('news-prev')?.addEventListener('click', () => {
      newsIndex = (newsIndex - 1 + newsCards.length) % newsCards.length;
      renderNews();
    });

    function formatStat(value, format) {
      if (format === 'million') return (value / 1000000).toFixed(0) + 'M';
      if (format === 'comma') return value.toLocaleString();
      if (format === 'currency-million') return '$' + (value / 1000000).toFixed(0) + 'M';
      return value.toString();
    }

    const counters = document.querySelectorAll('[data-counter]');
    const observer = new IntersectionObserver((entries, obs) => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        const target = Number(el.dataset.counter);
        const format = el.dataset.format;
        const duration = 1400;
        const start = performance.now();

        function tick(now) {
          const progress = Math.min((now - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.floor(target * eased);
          el.textContent = formatStat(current, format);
          if (progress < 1) requestAnimationFrame(tick);
          else {
            if (format === 'million') el.textContent = '12M';
            if (format === 'comma') el.textContent = '50,000';
            if (format === 'plain') el.textContent = '190';
            if (format === 'currency-million') el.textContent = '$850M';
          }
        }
        requestAnimationFrame(tick);
        obs.unobserve(el);
      });
    }, { threshold: 0.35 });

    counters.forEach(counter => observer.observe(counter));
  </script>
